"""Safe source inventory and secret indicators; never writes matching secret values."""
import ast
import hashlib
import importlib.metadata
import json
import re
import subprocess
from collections import Counter, defaultdict
from pathlib import Path

ROOT=Path(__file__).resolve().parents[2]
OUT=ROOT/'docs/audits/evidence'

def git(*args):
    return subprocess.check_output(['git',*args],cwd=ROOT)

def main():
    files=git('ls-files','-z').decode().split('\0')
    files=[f for f in files if f]
    inventory=[]; imports={}; parse_errors=[]; tests=[]; hashes=defaultdict(list)
    for filename in files:
        path=ROOT/filename
        if not path.is_file(): continue
        inventory.append(dict(path=filename,bytes=path.stat().st_size))
        if path.suffix in ('.py','.tsx','.ts','.js','.json','.sql'):
            hashes[hashlib.sha256(path.read_bytes()).hexdigest()].append(filename)
        if path.suffix=='.py':
            try:
                tree=ast.parse(path.read_text(encoding='utf-8-sig'))
                if filename.startswith('backend/api/'):
                    module='.'.join(Path(filename).with_suffix('').parts[1:])
                    imports[module]=[]
                    for n in ast.walk(tree):
                        if isinstance(n,ast.ImportFrom) and n.module and n.module.startswith('api.'):
                            imports[module].append(dict(module=n.module,line=n.lineno))
                if filename.startswith('backend/tests/'):
                    for n in ast.walk(tree):
                        if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef)) and n.name.startswith('test_'):
                            tests.append(dict(file=filename,test=n.name,line=n.lineno))
            except Exception as exc:
                parse_errors.append(dict(file=filename,error=type(exc).__name__))
    # Static cycles include deferred imports, which may be intentionally safe.
    graph={k:{e['module'] for e in edges if e['module'] in imports} for k,edges in imports.items()}
    cycles=set()
    def visit(node, trail):
        if node in trail:
            cycle=trail[trail.index(node):]
            rotations=[tuple(cycle[i:]+cycle[:i]) for i in range(len(cycle))]
            cycles.add(min(rotations)); return
        if len(trail)>=8: return
        for target in graph.get(node,[]):
            if target>=trail[0] if trail else True:
                visit(target,trail+[node])
    for node in graph: visit(node,[])
    indicators=[]
    patterns={
        'private_key':re.compile(rb'-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----'),
        'aws_access_key':re.compile(rb'\b(?:AKIA|ASIA)[A-Z0-9]{16}\b'),
        'github_token':re.compile(rb'\b(?:ghp_|gho_|ghs_)[A-Za-z0-9]{30,}\b'),
        'literal_secret_assignment':re.compile(rb'''(?i)(?:client_secret|clientsecret|api_key|password)\s*[=:]\s*["']([A-Za-z0-9_+/!@#$%^&*=-]{18,})["']'''),
    }
    # Current tracked tree plus every distinct reachable Git blob, not untracked credentials.
    objects={}
    for line in git('rev-list','--objects','--all').decode(errors='replace').splitlines():
        oid,_,name=line.partition(' ')
        if name: objects[oid]=name
    blob_count=0
    for oid,name in objects.items():
        kind=git('cat-file','-t',oid).strip()
        if kind!=b'blob': continue
        data=git('cat-file','-p',oid); blob_count+=1
        for rule,pattern in patterns.items():
            for match in pattern.finditer(data):
                indicators.append(dict(path=name,blob=oid,rule=rule,line=data[:match.start()].count(b'\n')+1,
                                       review='indicator only; value intentionally omitted'))
    versions={d.metadata['Name']:d.version for d in importlib.metadata.distributions() if d.metadata.get('Name')}
    result=dict(commit=git('rev-parse','HEAD').decode().strip(),tracked_files=len(files),
                module_files=inventory,python_parse_errors=parse_errors,test_inventory=tests,
                import_cycles_including_deferred=[list(c) for c in sorted(cycles)],
                exact_duplicate_sources=[v for v in hashes.values() if len(v)>1],
                history_blobs_scanned=blob_count,secret_indicators=indicators,
                secret_scan_limitations='Pattern based; no entropy/provider validation; absence of indicators does not prove absence of secrets.',
                installed_python_versions=versions)
    OUT.mkdir(parents=True,exist_ok=True)
    (OUT/'source-inventory.json').write_text(json.dumps(result,indent=2),encoding='utf-8')
    print(json.dumps(dict(tracked_files=len(files),python_parse_errors=len(parse_errors),
                         backend_test_methods=len(tests),import_cycles_including_deferred=len(cycles),
                         history_blobs_scanned=blob_count,secret_indicators=len(indicators))))

if __name__=='__main__': main()
